/* phrases avec des noms dedans (journal de combat, profils, tchat système) */
const I18N_RULES=[
 [/^(.+) frappe (.+) : #( k| M)?$/,(m)=>trN(m[1])+' hits '+trN(m[2])+': #'+(m[3]||'')],
 [/^(.+) est vaincue?\.$/,(m)=>trN(m[1])+' is defeated.'],
 [/^(.+) sont vaincus\.$/,(m)=>trN(m[1])+' are defeated.'],
 [/^Profil de (.+)$/,(m)=>m[1]+"'s profile"],
 [/^(.+) a rejoint (.+) après une annonce de recrutement\.$/,(m)=>m[1]+' joined '+m[2]+' after a recruitment post.'],
 [/^(.+) a rejoint (.+)\.$/,(m)=>m[1]+' joined '+m[2]+'.'],
 [/^Pseudo : (.+)$/,(m)=>'Username: '+m[1]],
 [/^(.+) soigne (.+) : #( k| M)?$/,(m)=>trN(m[1])+' heals '+trN(m[2])+': #'+(m[3]||'')],
 [/^🎲 Dé pipé : # ! Coup critique ×#$/,()=>'🎲 Loaded die: #! Critical hit ×#'],
 [/^(.+) est étourdie? et passe son tour\.$/,(m)=>trN(m[1])+' is stunned and skips their turn.'],
 [/^(.+) lance (.+) !$/,(m)=>trN(m[1])+' casts '+trN(m[2])+'!'],
 [/^(.+) utilise (.+) !$/,(m)=>trN(m[1])+' uses '+trN(m[2])+'!'],
 [/^(.+) a vaincu (.+) \(étape #\)\.$/,(m)=>m[1]+' defeated '+trN(m[2])+' (stage #).'],
 [/^(.+) a invoqué (.+) !$/,(m)=>m[1]+' summoned '+m[2]+'!'],
 [/^(.+) a infligé (.+) au boss\.$/,(m)=>m[1]+' dealt '+m[2]+' to the boss.'],
 [/^De (.+) · à l'instant$/,(m)=>'From '+trN(m[1])+' · just now'],
 [/^Vu il y a # (h|j|min) · (.+)$/,(m)=>'Seen # '+({h:'h',j:'d',min:'min'})[m[1]]+' ago · '+m[2]],
 [/^En ligne · (.+)$/,(m)=>'Online · '+m[1]],
];
function trN(s){if(LANG==='en'&&I18N_EN[s])return I18N_EN[s];const c=I18N.mem[s];return c!=null?c:s}
{const tk=trK;const plain=p=>!/[a-zà-ÿ]{3,}/.test(p)||/^[A-ZÀ-Ý][\wÀ-ÿ'’_-]{0,15}( ×#)?$/.test(p)||i18nNames().has(p);
 trK=function(k){const t=tk(k);if(t!=null)return t;if(LANG!=='en')return null;for(const [rx,f] of I18N_RULES){const m=k.match(rx);if(m){try{return f(m)}catch(e){}}}
  if(k.includes(' · ')||/ ·$/.test(k)){const tail=/ ·$/.test(k)?' ·':'';const P=k.replace(/ ·$/,'').split(' · ');let ok=0;const out=P.map(p=>{const q=p.trim();if(!q)return p;const x=tk(q);if(x!=null){ok++;return x}let r=null;for(const [rx,f] of I18N_RULES){const m=q.match(rx);if(m){try{r=f(m)}catch(e){}break}}if(r!=null){ok++;return r}return plain(q)?q:null});if(ok&&!out.includes(null))return out.join(' · ')+tail}
  return null}}
